68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final OwnerFieldsValidator ownerFieldsValidator;
84	
85	    private final RegistrationDateValidator registrationDateValidator;
86	
87	    private final RegistrationDateAssigner registrationDateAssigner;
88	
89	    private final MemberIdAssigner memberIdAssigner;
90	
91	    private final IdentityDuplicateChecker identityDuplicateChecker;
92	
93	    private final HouseholdAssigner householdAssigner;
94	
95	    private final HouseholdSizeAssigner householdSizeAssigner;
96	
97	    private final NamesakeCounter namesakeCounter;
98	
99	    private final MembershipLevelAssigner membershipLevelAssigner;
100	
101	    private final CityCapacityChecker cityCapacityChecker;
102	
103	    private final DailyRegistrationLimiter dailyRegistrationLimiter;
104	
105	    private final BulkSignupWarningAssigner bulkSignupWarningAssigner;
106	
107	    private final OwnerCreationAuditLogger ownerCreationAuditLogger;
108	
109	    private final PossibleDuplicateAssigner possibleDuplicateAssigner;
110	
111	    private final IdempotentOwnerStore idempotentOwnerStore;
112	
113	    private final WelcomeNotifier welcomeNotifier;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper,
119	                                 OwnerFieldsValidator ownerFieldsValidator,
120	                                 RegistrationDateValidator registrationDateValidator,
121	                                 RegistrationDateAssigner registrationDateAssigner,
122	                                 MemberIdAssigner memberIdAssigner,
123	                                 IdentityDuplicateChecker identityDuplicateChecker,
124	                                 HouseholdAssigner householdAssigner,
125	                                 HouseholdSizeAssigner householdSizeAssigner,
126	                                 NamesakeCounter namesakeCounter,
127	                                 MembershipLevelAssigner membershipLevelAssigner,
128	                                 CityCapacityChecker cityCapacityChecker,
129	                                 DailyRegistrationLimiter dailyRegistrationLimiter,
130	                                 BulkSignupWarningAssigner bulkSignupWarningAssigner,
131	                                 OwnerCreationAuditLogger ownerCreationAuditLogger,
132	                                 PossibleDuplicateAssigner possibleDuplicateAssigner,
133	                                 IdempotentOwnerStore idempotentOwnerStore,
134	                                 WelcomeNotifier welcomeNotifier) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	        this.ownerFieldsValidator = ownerFieldsValidator;
140	        this.registrationDateValidator = registrationDateValidator;
141	        this.registrationDateAssigner = registrationDateAssigner;
142	        this.memberIdAssigner = memberIdAssigner;
143	        this.identityDuplicateChecker = identityDuplicateChecker;
144	        this.householdAssigner = householdAssigner;
145	        this.householdSizeAssigner = householdSizeAssigner;
146	        this.namesakeCounter = namesakeCounter;
147	        this.membershipLevelAssigner = membershipLevelAssigner;
148	        this.cityCapacityChecker = cityCapacityChecker;
149	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
150	        this.bulkSignupWarningAssigner = bulkSignupWarningAssigner;
151	        this.ownerCreationAuditLogger = ownerCreationAuditLogger;
152	        this.possibleDuplicateAssigner = possibleDuplicateAssigner;
153	        this.idempotentOwnerStore = idempotentOwnerStore;
154	        this.welcomeNotifier = welcomeNotifier;
155	    }
156	
157	    @InitBinder("ownerFieldsDto")
158	    void initOwnerFieldsBinder(WebDataBinder binder) {
159	        binder.addValidators(ownerFieldsValidator, registrationDateValidator);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
165	        Collection<Owner> owners;
166	        if (lastName != null) {
167	            owners = this.clinicService.findOwnerByLastName(lastName);
168	        } else {
169	            owners = this.clinicService.findAllOwners();
170	        }
171	        if (owners.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
190	        if (StringUtils.hasText(idempotencyKey)) {
191	            Owner original = this.idempotentOwnerStore.find(idempotencyKey)
192	                .map(this.clinicService::findOwnerById)
193	                .orElse(null);
194	            if (original != null) {
195	                return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
196	            }
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
200	        this.registrationDateAssigner.assign(owner);
201	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        this.cityCapacityChecker.assignCapacityWarning(owner);
205	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
206	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
207	        }
208	        this.householdAssigner.assign(owner);
209	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
210	            return new ResponseEntity<>(HttpStatus.CONFLICT);
211	        }
212	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
213	        this.householdSizeAssigner.assign(owner);
214	        this.memberIdAssigner.assign(owner);
215	        this.namesakeCounter.assign(owner);
216	        this.membershipLevelAssigner.assign(owner);
217	        this.bulkSignupWarningAssigner.assign(owner);
218	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
219	        this.clinicService.saveOwner(owner);
220	        if (StringUtils.hasText(idempotencyKey)) {
221	            this.idempotentOwnerStore.remember(idempotencyKey, owner);
222	        }
223	        this.ownerCreationAuditLogger.logCreated(owner);
224	        this.welcomeNotifier.enqueueWelcome(owner);
