21	import org.springframework.validation.Errors;
22	import org.springframework.validation.ValidationUtils;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Validates an {@link OwnerFieldsDto} as part of the {@code @Valid} pass on the owner
27	 * request body: the address is canonicalised (preferring the structured {@code addressLine1}
28	 * /{@code addressLine2} fields when present, composing them into the stored {@code address},
29	 * and otherwise the flat {@code address}) and required to be present in either form; the
30	 * other required text fields must be present and non-blank; the telephone is canonicalised to E.164 form and
31	 * required to be a valid such number; an optional email is required to be syntactically
32	 * valid, not on a disposable-email-domain blocklist, and normalized to lower case; and an
33	 * optional postcode, when present, is required to
34	 * be a 4-digit code valid for the owner's city.
35	 * <p>
36	 * Registered on the owner controller through {@code @InitBinder} so every rejected field is
37	 * recorded as a field error on the shared {@link Errors}, surfacing through the usual
38	 * bad-request handling. The canonical address and a valid telephone (in E.164 form) are
39	 * written back to the DTO so they are stored, returned and compared for duplicates as those
40	 * canonical strings.
41	 *
42	 * @author Vitaliy Fedoriv
43	 */
44	@Component
45	public class OwnerFieldsValidator implements Validator {
46	
47	    private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "city", "telephone"};
48	
49	    private final TelephoneNormalizer telephoneNormalizer;
50	
51	    private final EmailNormalizer emailNormalizer;
52	
53	    private final AddressNormalizer addressNormalizer;
54	
55	    private final PostcodeValidator postcodeValidator;
56	
57	    private final DisposableEmailDomainChecker disposableEmailDomainChecker;
58	
59	    public OwnerFieldsValidator(TelephoneNormalizer telephoneNormalizer, EmailNormalizer emailNormalizer,
60	                                AddressNormalizer addressNormalizer, PostcodeValidator postcodeValidator,
61	                                DisposableEmailDomainChecker disposableEmailDomainChecker) {
62	        this.telephoneNormalizer = telephoneNormalizer;
63	        this.emailNormalizer = emailNormalizer;
64	        this.addressNormalizer = addressNormalizer;
65	        this.postcodeValidator = postcodeValidator;
66	        this.disposableEmailDomainChecker = disposableEmailDomainChecker;
67	    }
68	
69	    @Override
70	    public boolean supports(Class<?> clazz) {
71	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
72	    }
73	
74	    @Override
75	    public void validate(Object target, Errors errors) {
76	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
77	        normalizeAddress(owner, errors);
78	        for (String field : REQUIRED_FIELDS) {
79	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
80	        }
81	        if (!errors.hasFieldErrors("telephone")) {
82	            normalizeTelephone(owner, errors);
83	        }
84	        normalizeEmail(owner, errors);
85	        validatePostcode(owner, errors);
86	    }
87	
88	    /**
